const IMG1 = "data:image/jpeg;base64,";
const IMG2 = "data:image/jpeg;base64,";
const IMG3 = "data:image/jpeg;base64,";
const IMG4 = "data:image/jpeg;base64,";
const IMG5 = "data:image/jpeg;base64,";

// Injetar imagens
document.addEventListener('DOMContentLoaded', function() {
  const fotos = [IMG1, IMG2, IMG3, IMG4, IMG5];
  fotos.forEach(function(src, i) {
    var el = document.getElementById('foto' + (i+1));
    if (el) el.src = src;
  });
});

// CONTADOR PRINCIPAL
  function updateCounter() {
    const inicio = new Date('2025-09-06T00:00:00');
    const agora = new Date();
    const diff = agora - inicio;
    if (diff < 0) return;
    document.getElementById('c-dias').textContent     = Math.floor(diff / (1000*60*60*24));
    document.getElementById('c-horas').textContent    = Math.floor((diff % (1000*60*60*24)) / (1000*60*60));
    document.getElementById('c-minutos').textContent  = Math.floor((diff % (1000*60*60)) / (1000*60));
    document.getElementById('c-segundos').textContent = Math.floor((diff % (1000*60)) / 1000);
  }
  updateCounter();
  setInterval(updateCounter, 1000);

  // CAPSULA DO TEMPO
  const dataAbertura = new Date('2027-09-06T00:00:00');

  function updateCapsula() {
    const agora = new Date();
    const diff = dataAbertura - agora;

    if (diff <= 0) {
      document.getElementById('capsula-locked').style.display = 'none';
      document.getElementById('capsula-carta').classList.add('visivel');
      return;
    }

    const dias    = Math.floor(diff / (1000*60*60*24));
    const horas   = Math.floor((diff % (1000*60*60*24)) / (1000*60*60));
    const minutos = Math.floor((diff % (1000*60*60)) / (1000*60));
    const segundos= Math.floor((diff % (1000*60)) / 1000);

    document.getElementById('capsula-countdown').textContent =
      dias + 'd ' + horas + 'h ' + minutos + 'm ' + segundos + 's';
  }
  updateCapsula();
  setInterval(updateCapsula, 1000);

  // PARTICULAS
  const emojis = ['·', '·', '·', '*', '*'];
  const cont = document.getElementById('particles');
  for (let i = 0; i < 20; i++) {
    const el = document.createElement('div');
    el.className = 'particle';
    el.textContent = emojis[Math.floor(Math.random() * emojis.length)];
    el.style.left = Math.random() * 100 + 'vw';
    el.style.fontSize = (8 + Math.random() * 10) + 'px';
    el.style.color = ['#c8a8e9','#9d5ce6','#b08ad4','#7c3aed'][Math.floor(Math.random()*4)];
    el.style.animationDuration = (10 + Math.random() * 16) + 's';
    el.style.animationDelay = (Math.random() * 12) + 's';
    cont.appendChild(el);
  }